using System.IO.Compression;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Starlings.Models.EmbeddingGemma2;
#if STARLINGS_FFMPEG9
using Starlings.Models.EmbeddingGemma2.Video.FFmpeg9;
#else
using Starlings.Models.EmbeddingGemma2.Video.FFmpeg;
#endif

namespace Starlings.TestSupport;

/// <summary>
/// The accepted EmbeddingGemma 2 video fixtures (read only, in Git: <c>model-pipeline/protected/embeddinggemma-2/video-fp32-cpu</c>),
/// the video set (not in Git: regenerated byte for byte by <c>model-pipeline/reference/embeddinggemma2/make_eg2_videos.py</c>
/// with the pinned FFmpeg), the reference tensors (not in Git: <c>run_embeddinggemma2_video.py --tensors</c>, pinned by
/// <c>tensors.json</c>) and the user's FFmpeg shared libraries of the adapter's major (not in Git: FFmpeg 8 from <c>fetch_eg2_ffmpeg.sh</c>, LGPL
/// build; FFmpeg 9 for the FFmpeg 9 adapter's tests, compiled with STARLINGS_FFMPEG9).
/// Tests that need an absent asset skip with the reason.
/// </summary>
internal static class EmbeddingGemma2VideoTestAssets
{
    /// <summary>Directory holding the 22 videos from <c>make_eg2_videos.py</c>.</summary>
    public const string VideosEnvironmentVariable = "STARLING_EMBEDDINGGEMMA2_VIDEOS";

    /// <summary>Directory holding the reference <c>&lt;row id&gt;.npz</c> tensors (optional; soft-token and token-embedding checks).</summary>
    public const string TensorsEnvironmentVariable = "STARLING_EMBEDDINGGEMMA2_VIDEO_TENSORS";

    /// <summary>Directory of the FFmpeg 8.x shared libraries (the adapter's own variable).</summary>
    public const string FFmpegEnvironmentVariable = EmbeddingGemma2FFmpeg.LibraryDirectoryEnvironmentVariable;

    /// <summary>
    /// Set to <c>1</c> to accept a GPL FFmpeg build in the tests (<c>AllowNonLgplBuild</c>; decoding is identical), for
    /// example a distribution's FFmpeg 9. Unset (default): the LGPL build is required, as for users.
    /// </summary>
    public const string AllowNonLgplEnvironmentVariable = "STARLING_FFMPEG_ALLOW_NON_LGPL";

    /// <summary>Whether <see cref="AllowNonLgplEnvironmentVariable"/> is <c>1</c>.</summary>
    public static bool AllowNonLgplBuild => Environment.GetEnvironmentVariable(AllowNonLgplEnvironmentVariable) == "1";

    /// <summary>The fixture row that upstream embeds from a decoded array without metadata (rejected by default in C#).</summary>
    public const string NoMetadataRowId = "vid-array-no-metadata";

    /// <summary>Accepted video fixtures (PR #47).</summary>
    public static string FixtureDirectory => Path.Combine(EmbeddingGemma2TestAssets.ProtectedRoot, "video-fp32-cpu");

    /// <summary>The video set: <c>$STARLING_EMBEDDINGGEMMA2_VIDEOS</c>, else <c>&lt;models&gt;/embeddinggemma-2-videos</c>.</summary>
    public static string VideosDirectory =>
        Environment.GetEnvironmentVariable(VideosEnvironmentVariable) is { Length: > 0 } env
            ? env
            : Path.Combine(EmbeddingGemma2TestAssets.ModelsRoot, "embeddinggemma-2-videos");

    public static IReadOnlyList<VideoManifestEntry> Manifest { get; } = LoadManifest();

    public static IReadOnlyList<VideoRow> Rows { get; } = LoadRows();

    /// <summary>Per video: torchcodec's metadata, sampled indices and the SHA-256 of every decoded RGB frame.</summary>
    public static IReadOnlyDictionary<string, VideoFrames> Frames { get; } = LoadFrames();

    /// <summary>Null when every video file is present with its pinned SHA-256; otherwise the skip reason.</summary>
    public static string? VideosSkipReason { get; } = CheckVideos();

    /// <summary>Null when the FFmpeg directory is set; otherwise the skip reason.</summary>
    public static string? FFmpegSkipReason =>
        Environment.GetEnvironmentVariable(FFmpegEnvironmentVariable) is { Length: > 0 } dir && Directory.Exists(dir)
            ? null
            : $"set {FFmpegEnvironmentVariable} to the lib directory of an FFmpeg {EmbeddingGemma2FFmpeg.SupportedFFmpegMajor}.x shared build (LGPL; FFmpeg 8: model-pipeline/reference/embeddinggemma2/fetch_eg2_ffmpeg.sh) for the decoding tests; {AllowNonLgplEnvironmentVariable}=1 accepts a GPL build (a distribution FFmpeg).";

    public static string PathOf(string videoId) => Path.Combine(VideosDirectory, Manifest.Single(m => m.Id == videoId).File);

    private static readonly Lazy<EmbeddingGemma2VideoDecoder> SharedDecoder = new(() => new EmbeddingGemma2VideoDecoder(new EmbeddingGemma2FFmpegOptions { AllowNonLgplBuild = AllowNonLgplBuild }));

    /// <summary>The adapter on the FFmpeg directory of the environment; skips the calling test without videos or FFmpeg.</summary>
    public static EmbeddingGemma2VideoDecoder Decoder
    {
        get
        {
            Assert.SkipWhen(VideosSkipReason is not null, VideosSkipReason ?? string.Empty);
            Assert.SkipWhen(FFmpegSkipReason is not null, FFmpegSkipReason ?? string.Empty);
            return SharedDecoder.Value;
        }
    }

    private static readonly Dictionary<string, EmbeddingGemma2DecodedVideo> DecodedCache = new(StringComparer.Ordinal);

    /// <summary>A fixture video decoded by the adapter (upstream's sampled frames), cached.</summary>
    public static EmbeddingGemma2DecodedVideo Decode(string videoId)
    {
        var decoder = Decoder;
        lock (DecodedCache)
        {
            if (!DecodedCache.TryGetValue(videoId, out var video))
            {
                video = decoder.DecodeFile(PathOf(videoId), TestContext.Current.CancellationToken);
                DecodedCache[videoId] = video;
            }

            return video;
        }
    }

    /// <summary>
    /// The input of a fixture row from adapter-decoded videos: path, decoder-object and caption rows from
    /// <see cref="EmbeddingGemma2VideoDecoder.DecodeFile"/>; the array rows from every decoded frame, with the timing
    /// (<see cref="EmbeddingGemma2Video.FromDecodedFrames"/>) or without (<see cref="EmbeddingGemma2Video.FromFramesWithoutTiming"/>).
    /// </summary>
    public static EmbeddingGemma2MultimodalInput BuildInput(VideoRow row)
    {
        var videos = row.Videos.Select(v => v.InputForm switch
        {
            "array+metadata" => AllFrames(v.Video).Video,
            "array" => EmbeddingGemma2Video.FromFramesWithoutTiming(AllFrames(v.Video).Video.Frames),
            _ => Decode(v.Video).Video,
        }).ToList();
        EmbeddingGemma2Image? still = row.Image is { } img ? Decoder.DecodeFramesAt(PathOf(img.Video), [img.FrameIndex])[0] : null;
        return BuildInput(row, videos, still);
    }

    /// <summary>Upstream's layout: placeholders in the text mark media positions; without any, images then videos follow the text.</summary>
    public static EmbeddingGemma2MultimodalInput BuildInput(VideoRow row, IReadOnlyList<EmbeddingGemma2Video> videos, EmbeddingGemma2Image? still)
    {
        if (row.Text is null)
        {
            var media = new List<object>();
            if (still is not null)
            {
                media.Add(still);
            }

            media.AddRange(videos);
            return media.Count == 0 ? EmbeddingGemma2MultimodalInput.FromText(string.Empty) : EmbeddingGemma2MultimodalInput.Create(media);
        }

        if (videos.Count == 0 && still is null)
        {
            return EmbeddingGemma2MultimodalInput.FromText(row.Text);
        }

        var parts = new List<object>();
        int v = 0;
        bool imageUsed = false;
        int start = 0;
        while (true)
        {
            int iv = row.Text.IndexOf("<|video|>", start, StringComparison.Ordinal);
            int ii = row.Text.IndexOf("<|image|>", start, StringComparison.Ordinal);
            int next = iv < 0 ? ii : ii < 0 ? iv : Math.Min(iv, ii);
            if (next < 0)
            {
                parts.Add(row.Text[start..]);
                break;
            }

            parts.Add(row.Text[start..next]);
            if (next == iv)
            {
                parts.Add(videos[v++]);
            }
            else
            {
                parts.Add(still!);
                imageUsed = true;
            }

            start = next + "<|video|>".Length;
        }

        if (v == 0 && !imageUsed)
        {
            // No placeholder: images, then videos, after the text (the chat template's order).
            if (still is not null)
            {
                parts.Add(still);
            }

            parts.AddRange(videos);
        }
        else
        {
            Assert.Equal(videos.Count, v);
        }

        return EmbeddingGemma2MultimodalInput.Create(parts);
    }

    private static readonly Dictionary<string, EmbeddingGemma2DecodedVideo> AllFramesCache = new(StringComparer.Ordinal);

    /// <summary>Every decoded frame of a fixture video (with timing), cached; only for the short array rows.</summary>
    public static EmbeddingGemma2DecodedVideo AllFrames(string videoId)
    {
        var decoder = Decoder;
        lock (AllFramesCache)
        {
            if (!AllFramesCache.TryGetValue(videoId, out var video))
            {
                video = decoder.DecodeAllFrames(PathOf(videoId), TestContext.Current.CancellationToken);
                AllFramesCache[videoId] = video;
            }

            return video;
        }
    }

    /// <summary>Zero frames of a video's decoded size and sampled count (rendering and tokenization depend only on those).</summary>
    public static EmbeddingGemma2Video SizedPlaceholder(VideoRowVideo v)
    {
        var frame = EmbeddingGemma2Image.FromRgb24(v.DecodedWidth, v.DecodedHeight, new byte[(long)v.DecodedWidth * v.DecodedHeight * 3]);
        return EmbeddingGemma2Video.FromSampledFrames(Enumerable.Repeat(frame, v.SampledIndices.Length).ToArray());
    }

    /// <summary>The tensors directory, or null with the reason.</summary>
    public static (string? Directory, string Reason) FindTensors()
    {
        string? dir = Environment.GetEnvironmentVariable(TensorsEnvironmentVariable);
        if (string.IsNullOrEmpty(dir) || !Directory.Exists(dir))
        {
            return (null, $"set {TensorsEnvironmentVariable} to the directory of run_embeddinggemma2_video.py --tensors output (<row id>.npz) for the soft-token and token-embedding checks.");
        }

        return (dir, string.Empty);
    }

    private static readonly JsonElement TensorDigests = JsonDocument.Parse(File.ReadAllText(Path.Combine(FixtureDirectory, "tensors.json"))).RootElement;

    /// <summary>SHA-256 of a reference tensor (from <c>tensors.json</c>).</summary>
    public static string TensorSha256(string rowId, string name) => TensorDigests.GetProperty(rowId).GetProperty(name).GetProperty("sha256").GetString()!;

    /// <summary>A float32 array of a row's <c>.npz</c>, checked against the SHA-256 in <c>tensors.json</c>.</summary>
    public static float[] ReadReferenceTensor(string directory, string rowId, string name)
    {
        using var zip = ZipFile.OpenRead(Path.Combine(directory, rowId + ".npz"));
        var entry = zip.GetEntry(name + ".npy") ?? throw new InvalidDataException($"{rowId}.npz has no {name}.");
        using var stream = entry.Open();
        using var buffer = new MemoryStream();
        stream.CopyTo(buffer);
        var bytes = buffer.ToArray();
        if (bytes.Length < 10 || bytes[0] != 0x93 || Encoding.ASCII.GetString(bytes, 1, 5) != "NUMPY")
        {
            throw new InvalidDataException($"{rowId}/{name}: not an .npy file");
        }

        int headerLength = bytes[6] == 1 ? BitConverter.ToUInt16(bytes, 8) : BitConverter.ToInt32(bytes, 8);
        int offset = (bytes[6] == 1 ? 10 : 12) + headerLength;
        string header = Encoding.ASCII.GetString(bytes, bytes[6] == 1 ? 10 : 12, headerLength);
        if (!header.Contains("'descr': '<f4'", StringComparison.Ordinal) || header.Contains("'fortran_order': True", StringComparison.Ordinal))
        {
            throw new InvalidDataException($"{rowId}/{name}: expected C-ordered little-endian float32, header {header}");
        }

        var data = bytes.AsSpan(offset);
        string actual = Convert.ToHexStringLower(SHA256.HashData(data));
        if (actual != TensorSha256(rowId, name))
        {
            throw new InvalidDataException($"{rowId}/{name}: SHA-256 {actual} differs from tensors.json; not the reference tensors.");
        }

        return MemoryMarshal.Cast<byte, float>(data).ToArray();
    }

    /// <summary>SHA-256 of raw values, as the reference's <c>sha(np.ascontiguousarray(a).tobytes())</c>.</summary>
    public static string Sha<T>(ReadOnlySpan<T> values)
        where T : unmanaged => Convert.ToHexStringLower(SHA256.HashData(MemoryMarshal.AsBytes(values)));

    /// <summary>SHA-256 of several arrays concatenated (frames of a video in order).</summary>
    public static string Sha<T>(IEnumerable<ReadOnlyMemory<T>> parts)
        where T : unmanaged
    {
        using var hash = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
        foreach (var part in parts)
        {
            hash.AppendData(MemoryMarshal.AsBytes(part.Span));
        }

        return Convert.ToHexStringLower(hash.GetHashAndReset());
    }

    private static List<VideoManifestEntry> LoadManifest()
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(Path.Combine(FixtureDirectory, "videos.json")));
        return doc.RootElement.GetProperty("videos").EnumerateArray().Select(v => new VideoManifestEntry(
            v.GetProperty("id").GetString()!,
            v.GetProperty("file").GetString()!,
            v.GetProperty("sha256").GetString()!,
            v.GetProperty("codec").GetString()!,
            v.GetProperty("bits").GetInt32(),
            v.GetProperty("rotation").GetInt32(),
            v.GetProperty("scene").GetString()!)).ToList();
    }

    private static Dictionary<string, VideoFrames> LoadFrames()
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(Path.Combine(FixtureDirectory, "video-frames.json")));
        var result = new Dictionary<string, VideoFrames>(StringComparer.Ordinal);
        foreach (var p in doc.RootElement.EnumerateObject())
        {
            result[p.Name] = new VideoFrames(
                ReadMetadata(p.Value.GetProperty("metadata"))!,
                p.Value.GetProperty("sampled_indices").EnumerateArray().Select(e => e.GetInt32()).ToArray(),
                p.Value.GetProperty("all_frame_sha256").EnumerateArray().Select(e => e.GetString()!).ToArray());
        }

        return result;
    }

    private static VideoFixtureMetadata? ReadMetadata(JsonElement m) =>
        m.ValueKind == JsonValueKind.Null
            ? null
            : new VideoFixtureMetadata(
                m.GetProperty("num_frames").GetInt32(),
                m.GetProperty("average_fps").GetDouble(),
                m.GetProperty("duration_seconds").GetDouble(),
                m.GetProperty("begin_stream_seconds").GetDouble(),
                m.GetProperty("end_stream_seconds").GetDouble(),
                m.GetProperty("width").GetInt32(),
                m.GetProperty("height").GetInt32(),
                m.GetProperty("codec").GetString()!,
                m.GetProperty("rotation").ValueKind == JsonValueKind.Null ? null : m.GetProperty("rotation").GetDouble());

    private static List<VideoRow> LoadRows() =>
        EmbeddingGemma2TestAssets.ReadJsonLines(Path.Combine(FixtureDirectory, "video-embeddings.jsonl"))
            .Select(r => new VideoRow(
                r.GetProperty("id").GetString()!,
                r.GetProperty("kind").GetString()!,
                r.GetProperty("input_form").GetString()!,
                r.GetProperty("prompt").GetString()!,
                r.GetProperty("text").ValueKind == JsonValueKind.Null ? null : r.GetProperty("text").GetString(),
                r.GetProperty("image").ValueKind == JsonValueKind.Null
                    ? null
                    : new VideoRowImage(r.GetProperty("image").GetProperty("video").GetString()!, r.GetProperty("image").GetProperty("frame_index").GetInt32()),
                r.GetProperty("videos").EnumerateArray().Select(v => new VideoRowVideo(
                    v.GetProperty("video").GetString()!,
                    v.GetProperty("input_form").GetString()!,
                    ReadMetadata(v.GetProperty("metadata")),
                    v.GetProperty("sampled_indices").EnumerateArray().Select(e => e.GetInt32()).ToArray(),
                    v.GetProperty("decoded").GetProperty("width").GetInt32(),
                    v.GetProperty("decoded").GetProperty("height").GetInt32(),
                    v.GetProperty("resized").GetProperty("width").GetInt32(),
                    v.GetProperty("resized").GetProperty("height").GetInt32(),
                    v.GetProperty("soft_tokens_per_frame").GetInt32(),
                    v.TryGetProperty("frame_sha256", out var fs) ? fs.EnumerateArray().Select(e => e.GetString()!).ToArray() : [],
                    v.GetProperty("digests").GetProperty("frames_uint8").GetString()!,
                    v.GetProperty("digests").GetProperty("resized_uint8").GetString()!,
                    v.GetProperty("digests").GetProperty("pixel_values").GetString()!,
                    v.GetProperty("digests").GetProperty("positions").GetString()!)).ToList(),
                r.GetProperty("input_ids").EnumerateArray().Select(e => e.GetInt64()).ToArray(),
                r.GetProperty("embedding").EnumerateArray().Select(e => e.GetSingle()).ToArray()))
            .ToList();

    private static string? CheckVideos()
    {
        string dir = VideosDirectory;
        foreach (var m in Manifest)
        {
            string path = Path.Combine(dir, m.File);
            if (!File.Exists(path))
            {
                return $"video set not found ({path}); regenerate it with model-pipeline/reference/embeddinggemma2/make_eg2_videos.py --out <dir> (pinned FFmpeg GPL build from fetch_eg2_ffmpeg.sh) and set {VideosEnvironmentVariable}.";
            }

            string sha = Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(path)));
            if (sha != m.Sha256)
            {
                throw new InvalidDataException($"{path}: SHA-256 {sha} differs from videos.json {m.Sha256}; not the fixture video set.");
            }
        }

        return null;
    }
}

/// <summary>One video of <c>videos.json</c>.</summary>
internal sealed record VideoManifestEntry(string Id, string File, string Sha256, string Codec, int Bits, int Rotation, string Scene);

/// <summary>torchcodec's metadata as the fixtures record it.</summary>
internal sealed record VideoFixtureMetadata(int NumFrames, double AverageFps, double DurationSeconds, double BeginSeconds, double EndSeconds, int Width, int Height, string Codec, double? Rotation);

/// <summary>One video of <c>video-frames.json</c>.</summary>
internal sealed record VideoFrames(VideoFixtureMetadata Metadata, int[] SampledIndices, string[] AllFrameSha256);

/// <summary>The still image of a row: a decoded frame of a fixture video.</summary>
internal sealed record VideoRowImage(string Video, int FrameIndex);

/// <summary>One video of a fixture row, with the reference digests of its frames and preprocessing.</summary>
internal sealed record VideoRowVideo(
    string Video,
    string InputForm,
    VideoFixtureMetadata? Metadata,
    int[] SampledIndices,
    int DecodedWidth,
    int DecodedHeight,
    int ResizedWidth,
    int ResizedHeight,
    int SoftTokensPerFrame,
    string[] FrameSha256,
    string FramesSha256,
    string ResizedSha256,
    string PixelValuesSha256,
    string PositionsSha256);

/// <summary>One row of <c>video-embeddings.jsonl</c>.</summary>
internal sealed record VideoRow(string Id, string Kind, string InputForm, string Prompt, string? Text, VideoRowImage? Image, IReadOnlyList<VideoRowVideo> Videos, long[] InputIds, float[] Embedding)
{
    public EmbeddingGemma2Prompt PackagePrompt => EmbeddingGemma2Prompt.FromName(Prompt);

    /// <summary>True when the row is in the default C# contract (the metadata-less array row needs the opt-in).</summary>
    public bool InDefaultContract => Id != EmbeddingGemma2VideoTestAssets.NoMetadataRowId;
}
